package cli

import (
	"github.com/spf13/cobra"
)

// newHookCmd builds `vmono hook`, the entry points that harness integrations
// call on their own. It is hidden from help: nobody types these, and the
// integrations that call them are generated by vmono itself.
func newHookCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:    "hook",
		Short:  "Entry points that harness integrations call",
		Hidden: true,
	}
	cmd.AddCommand(newHookSessionStartCmd())
	return cmd
}

// newHookSessionStartCmd builds `vmono hook session-start`, which the Claude
// Code plugin runs when a conversation starts, resumes, or is compacted. It
// prints the live state of the session the working directory is in, which
// Claude Code adds to the conversation as context, so the agent knows each
// member's branch, what is uncommitted and what is left to push without
// having to ask.
//
// It must never get in the way of a conversation. Outside a session it prints
// nothing, and any failure to load the package or read git is treated the
// same way: nothing is printed and the exit status is 0.
func newHookSessionStartCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "session-start",
		Short: "Print the current session's live state as context for an agent",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			c, err := loadCore()
			if err != nil {
				return nil
			}
			// ResolveContext returns a session only when the working
			// directory is inside one, unlike ResolveSession, which falls
			// back to a package's sole session.
			_, s, err := c.ResolveContext("")
			if err != nil || s == nil {
				return nil
			}
			out := cmd.OutOrStdout()
			fprintf(out, "You are working inside a vmono session. Its state right now:\n\n")
			if err := writeStatusText(out, c.Status(s)); err != nil {
				return nil
			}
			fprintf(out, "\nThe vmono skill explains how to read and update the package. "+
				"Commands: /vmono:status, /vmono:note [text], /vmono:push.\n")
			return nil
		},
	}
}
